"""Generate the full-film and bounded video-only replacement tables."""
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]


def load_json(name):
    return json.loads((ROOT / 'config' / name).read_text(encoding='utf8'))


def render(streams, edits):
    rows = sorted({
        (s['disc'], s['fad'], s['sectors'],
         int(s['movie'][5:]) if s.get('movie', '').startswith('MOVIE') and not s.get('alternate_cut') else -1)
        for s in streams
    })
    out = [
        '// SPDX-License-Identifier: GPL-3.0-only',
        '// Generated by tools/gen_film_clip_table.py from config/film-*.json: do not edit.',
        '#pragma once',
        '#include <array>',
        '#include <cstdint>',
        '#include <span>',
        'namespace port {',
        'struct FilmClip {uint8_t disc;uint32_t fad;uint32_t sectors;int16_t movie;};',
        f'inline constexpr FilmClip kFilmClips[{len(rows)}]={{',
    ]
    out.extend(f'    {{{d},0x{f:X},{n},{m}}},' for d, f, n, m in rows)
    out.extend([
        '};',
        f'inline constexpr unsigned kFilmClipCount={len(rows)};',
        'struct FilmVideoSpan { unsigned saturnBegin, saturnEnd, pcStartMilliseconds, pcEndMilliseconds; };',
        'struct FilmVideoEdit {',
        '    int disc, movie;',
        '    uint32_t fad, sectors;',
        '    uint64_t pcBytes;',
        '    std::span<const FilmVideoSpan> spans;',
        '};',
    ])

    video_rows = []
    seen_streams = set()
    for edit in sorted(edits, key=lambda e: (e['disc'], e['movie'])):
        disc, movie = edit['disc'], edit['movie']
        candidates = [s for s in streams if (s['disc'], s.get('movie')) == (disc, movie)]
        if (disc, movie) in seen_streams or len(candidates) != 1 or not candidates[0]['alternate_cut']:
            raise ValueError(f'{disc}/{movie} must identify one unused alternate Saturn edit')
        seen_streams.add((disc, movie))
        source = candidates[0]
        size, spans = edit['pc_bytes'], edit['spans']
        if type(size) is not int or size <= 0 or not spans:
            raise ValueError(f'{disc}/{movie} requires a donor byte count and spans')
        # Native fields and donor millisecond positions use exclusive end bounds.
        # Nominal film lengths are rounded up to the next available field/millisecond.
        saturn_limit = int(source['duration'] * 59.82) + 1
        pc_limit = int(source['pc_duration'] * 1000) + 1
        name = f'kVideo{disc}{movie}'
        out.append(f'inline constexpr FilmVideoSpan {name}[]={{')
        next_saturn, next_pc = 0, 0
        for span in spans:
            if len(span) != 4 or any(type(position) is not int for position in span):
                raise ValueError(f'{disc}/{movie} spans require four integer positions')
            a, b, c, d = span
            if not (next_saturn <= a < b <= saturn_limit and next_pc <= c < d <= pc_limit):
                raise ValueError(f'{disc}/{movie} span overlaps or exceeds the source timeline: {span}')
            out.append(f'    {{{a}, {b}, {c}, {d}}},')
            next_saturn, next_pc = b, d
        out.append('};')
        video_rows.append(f'    {{{disc}, {int(movie[5:])}, 0x{source["fad"]:X}, '
                          f'{source["sectors"]}, {size}, {name}}},')

    out.append(f'inline constexpr std::array<FilmVideoEdit, {len(video_rows)}> kVideoEdits={{{{')
    out.extend(video_rows)
    out.extend([
        '}};',
        'inline const FilmVideoEdit* FindFilmVideoEdit(int disc, uint32_t fad) {',
        '    for (const auto& edit : kVideoEdits)',
        '        if (edit.disc == disc && fad >= edit.fad && fad - edit.fad < edit.sectors)',
        '            return &edit;',
        '    return nullptr;',
        '}',
        '}',
    ])
    return '\n'.join(out) + '\n'


if __name__ == '__main__':
    streams = load_json('film-fad-map.json')['streams']
    edits = load_json('film-video-spans.json')['edits']
    target = Path(sys.argv[1]) if len(sys.argv) > 1 else ROOT / 'local/deps/satrecomp/port/film_clip_table.h'
    target.write_text(render(streams, edits), encoding='utf8', newline='\n')
    print(len(streams), 'streams and', len(edits), 'bounded video edits ->', target)
